document.addEventListener("DOMContentLoaded",function(){const daysInput=document.getElementById("daysInput");if(!daysInput)return;const totalKm=document.getElementById("totalKm");const resultValue=document.getElementById("resultValue");const kmPerDay=200;function calculateMileage(){const days=parseInt(daysInput.value)||1;const total=days*kmPerDay;const formattedTotal=total.toLocaleString("en-US");totalKm.textContent=formattedTotal;resultValue.textContent=formattedTotal+" KM";totalKm.style.transform="scale(1.1)";resultValue.style.transform="scale(1.05)";setTimeout(()=>{totalKm.style.transform="scale(1)";resultValue.style.transform="scale(1)"},200)}daysInput.addEventListener("input",calculateMileage);daysInput.addEventListener("change",function(){if(this.value<1)this.value=1;if(this.value>365)this.value=365;calculateMileage()});totalKm.style.transition="transform 0.2s ease";resultValue.style.transition="transform 0.2s ease"});(function(){if(window.innerWidth<=991){function forceWhiteText(){const selectors=["header a","header li","#mainmenu a","#mainmenu li","#mainmenu span","#de-sidebar a","#de-sidebar li","#de-sidebar span",".de-menu-profile a",".de-menu-profile li",".de-menu-profile span","nav a","nav li","nav span"];selectors.forEach(selector=>{const elements=document.querySelectorAll(selector);elements.forEach(el=>{if(!el.closest("#logo")&&!el.closest(".lang-picker-wrapper")&&!el.closest(".call-now-btn")){el.style.setProperty("color","#ffffff","important")}})})}forceWhiteText();setTimeout(forceWhiteText,100);setTimeout(forceWhiteText,500);const menuBtn=document.getElementById("menu-btn");if(menuBtn){menuBtn.addEventListener("click",function(){setTimeout(forceWhiteText,50);setTimeout(forceWhiteText,200)})}const observer=new MutationObserver(function(mutations){forceWhiteText()});observer.observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:["class","style"]});window.addEventListener("resize",forceWhiteText)}})();